$:set -euo pipefail
if test -f README.md; then cat README.md >/dev/null; fi
cat AGENTS.md >/dev/null
gh api repos/BestNameYet/Terminals/issues/3 --jq .body >/dev/null
gh auth setup-git
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
node <<'NODE'
"use strict";
const fs=require("fs"),assert=require("assert");
const original="Tasks/User Prompt Task Queue/user-prompt-task-1794193447-wrapper-draft.json";
const acceptedSource="Tasks/TasksCompleted/user-prompt-task-1794193968-rule.json";
const target="references/conversation-analytics-rule.json";
assert(!fs.existsSync(target),"Target already exists; refusing overwrite");
const wrapper=JSON.parse(fs.readFileSync(original,"utf8"));
const reference=JSON.parse(fs.readFileSync(acceptedSource,"utf8"));
assert(Array.isArray(wrapper)&&wrapper.length===3&&!Array.isArray(wrapper[2]));
const rule=wrapper[2];
assert(rule.title==="End-of-Turn Conversation Analytics Recording");
const {title,...body}=rule;
assert.deepStrictEqual(body,reference[1],"Source body mismatch");
fs.writeFileSync(target,JSON.stringify(rule,null,2)+"\n","utf8");
const readback=JSON.parse(fs.readFileSync(target,"utf8"));
assert.deepStrictEqual(readback,rule,"Reference copy mismatch");
console.log("PERSISTED",target);
console.log("TITLE",readback.title);
console.log("MATCHES_WRAPPER_OBJECT",true);
console.log("MATCHES_ACCEPTED_ANALYTICS_BODY",true);
console.log("BYTES",fs.statSync(target).size);
NODE
git add -- references/conversation-analytics-rule.json
git diff --cached --check
git commit -m 'Add standalone conversation analytics rule to references'
for i in 1 2 3 4; do
  git fetch origin main -q
  git rebase origin/main -q
  if git push origin HEAD:main; then break; fi
  test "$i" -lt 4
done
printf 'PUBLISHED_COMMIT '; git rev-parse HEAD
git show --stat --oneline HEAD
